def _analyze(self, oFile, oLine, iLineNumber):
    if oLine.__dict__[self.sTrigger]:
        words = self._extract(oLine)

        # ToDo: Raise exception when case differs from lower and upper
        if self.case == 'lower':
            check_function = check.is_lowercase
        else:
            check_function = check.is_uppercase

        for word in words:
            if check_function(self, word, iLineNumber) == False:
                self.words_to_fix.add(word)

        # Raise exception if case does not match
        if (self.case == 'lower' and any(word.isupper() for word in words)) or (self.case == 'upper' and any(word.islower() for word in words)):
            raise ValueError('Case mismatch: expected {} but found mixed case in words.'.format(self.case))
